from author import *
c=C('数项级数的敛散性')
S(c,'级数先看部分和与通项',[R('级数与前N项部分和',r'a_1+a_2+\cdots,\qquad S_N=a_1+a_2+\cdots+a_N'),T('必要条件','级数收敛 ⇒ 通项趋于零；反向不成立'),T('反过来不成立','调和级数∑1/n发散，但它的通项1/n趋于零')],[P('先把每一项逐个加到部分和上。级数问的是这些部分和能否趋于一个有限数，不是只看单个项是否越来越小。一个快速必要条件是，通项必须趋于零；若通项不趋零，可以直接判发散。比如每项始终是一，部分和不断增长，根本不必再使用比值或比较判别。',[1,2],['先看通项是否趋零','级数收敛关注部分和的有限极限'],phase='partial',anchor='先把每一项逐个加到部分和上'),P('现在对比调和级数的部分和。它的通项一除以n确实趋零，但部分和仍然不断增长，所以发散。零通项只通过第一道筛选，不是收敛证明。考试里看到通项极限为零后，要继续根据正项、交错、阶乘、幂等结构选判别法，不能在必要条件处提前写收敛。',[3],['通项趋零只是必要条件','调和级数提供常用反例'],phase='harmonic',anchor='现在对比调和级数的部分和')],['级数与收敛必要条件'],visual=G('partial_sums'))
S(c,'几何级数与p级数是比较基准',[R('从零项起的几何级数',r'\sum_{n=0}^{\infty}q^n=\frac1{1-q}\quad(|q|<1)'),R('起点改变，和也改变',r'\sum_{n=1}^{\infty}\left(\frac12\right)^n=1,\quad\sum_{n=0}^{\infty}\left(\frac12\right)^n=2'),R('p级数：p>1收敛，p≤1发散',r'\sum_{n=1}^{\infty}\frac1{n^p}')],[P('几何级数，也叫等比级数，收敛条件是公比绝对值小于一。求和公式要看首项；从n等于零开始，第一项是一，从n等于一开始，第一项变成q。因此例题的两个和分别是一与二，不能只看到二分之一的n次方，就不看下标照抄同一个数。',[1,2],['等比级数先看公比绝对值','求和必须核对起始下标']),P('第二个常用基准是p级数：一除以n的p次方相加，p大于一收敛，p小于等于一发散。尤其p等于一是调和级数，不能划进收敛那一边。以后比较复杂正项级数时，经常先判断它与一除以n、或一除以n平方接近，再借这两个基准确定敛散性。',[3],['p必须严格大于一才收敛','p等于一是最重要的边界'])],['几何级数与p级数'])
S(c,'正项比较：选对上下界方向',[R('上界收敛可推出本项收敛',r'0<\frac1{n^2+n}\leq\frac1{n^2}'),R('极限比较的例题',r'\lim_{n\to\infty}\frac{1/\sqrt{n^2+1}}{1/n}=1'),T('本例结论','前者收敛；后者与调和级数同敛散，故发散')],[P('正项比较法要注意方向。如果大的一串都能加成有限数，小的一串也收敛。本题一除以n平方加n，不超过一除以n平方，所以上界收敛，原级数收敛。反过来，用一个发散的大上界，不能推出小的也发散；大到小、小到大的推理方向不能混用。',[1],['较大上界收敛，推出较小项收敛','发散的上界通常不能给出所需结论']),P('结构相近时用极限比较更方便。第二题与一除以n相除，极限为一，是有限正数，因此二者同敛散，原级数发散。这里使用的是极限落在零与正无穷之间的标准情形；如果极限恰为零或无穷，要重新判断具体方向，不能继续机械写同敛散。',[2,3],['有限正的比较极限给出同敛散','零或无穷不能照搬这条结论'])],['正项级数比较判别'])
S(c,'比值与根值：看到结构再选择',[R('含阶乘的例题',r'a_n=\frac{2^n}{n!},\quad\lim\frac{a_{n+1}}{a_n}=\lim\frac2{n+1}=0'),R('n次幂的例题',r'a_n=\left(\frac{n}{2n+1}\right)^n,\quad\lim\sqrt[n]{a_n}=\frac12'),T('判别规则','ρ<1：绝对收敛；ρ>1（含无穷）：发散'),T('边界情况','ρ等于1时，比值法或根值法通常无法判定')],[P('含阶乘时优先试比值法，把下一项除以当前项，常能大量约分。本题二的n次方除以n阶乘，下一项比当前项是二除以n加一，极限零，小于一，收敛。先把下一项完整写出来，尤其阶乘要改成n加一的阶乘，不能只改指数而把分母留在原处。',[1],['阶乘常适合比值法','有正负时通常先取绝对值']),P('整个括号的n次幂，常适合根值法，开n次方后只剩括号里的量，本例极限二分之一，收敛。两种判别的边界都是一：小于一收敛，大于一发散，等于一则没有结论。调和级数与平方倒数级数的比值极限都为一，结果却不同，正好说明这个边界不能随意判。',[2,3,4],['整项n次幂可试根值法','极限等于一时换方法'])],['比值与根值判别'])
S(c,'交错级数：还要检查单调与趋零',[R('满足这些条件，交错级数收敛',r'a_n=(-1)^{n-1}b_n,\quad b_n\geq0,\quad b_n\downarrow0'),R('交错调和级数收敛',r'1-\frac12+\frac13-\frac14+\cdots'),R('截断误差估计',r'|S-S_N|\leq b_{N+1};\quad N=100:\quad |R_N|\leq\frac1{101}')],[P('先看交错加减后的部分和。莱布尼茨法要求正的项大小最终单调不增，并趋于零，不是有正负交替就自动收敛。本例一除以n递减到零，所以交错调和级数收敛。题目若在分子加上让项大小不趋零的部分，就不能继续仅凭交错符号使用这条规则。',[1,2],['最终单调不增并且趋零','有交错符号不等于条件都满足'],phase='alternate',anchor='先看交错加减后的部分和'),P('现在用下一项的大小框出误差。满足相应条件时，前N项部分和的误差绝对值不超过下一项。本题取一百项，误差不超过一除以一百零一。这个简便估计是交错结构带来的，不能把它无条件用于任意正项级数。若要求小于指定误差，就解下一项大小对应的不等式。',[3],['误差看第N加一项','该估计有交错与单调条件'],phase='error',anchor='现在用下一项的大小框出误差')],['交错级数与误差'],visual=G('alternating'))
S(c,'绝对收敛与条件收敛',[T('绝对收敛的定义','∑|aₙ|收敛，称为绝对收敛；可推出∑aₙ收敛'),R('条件收敛：原级数收敛，绝对值级数发散',r'\sum\frac{(-1)^{n-1}}n,\qquad\sum\frac1n'),R('绝对收敛：绝对值级数也收敛',r'\sum\frac{(-1)^{n-1}}{n^2},\qquad\sum\frac1{n^2}')],[P('判断绝对与条件，先把每项取绝对值再检查。绝对值级数收敛，就叫绝对收敛，也能推出原级数收敛。若原级数收敛、绝对值级数发散，才叫条件收敛。不能只算出绝对值级数发散，就直接宣布原级数发散，因为正负抵消可能让原级数仍然收敛。',[1,2],['先检查绝对值级数','绝对值发散，原级数仍需另判']),P('交错调和级数是条件收敛；分母换成n平方，取绝对值后是收敛的p级数，所以绝对收敛。做题顺序可以固定为通项筛选、绝对值判断、必要时再用交错条件。条件收敛级数的项不能随意重排后仍断言和不变，这一点与有限个数相加的习惯不同，基础题按给定顺序处理。',[3],['平方分母的交错例题绝对收敛','条件收敛时不随意重排项'])],['绝对与条件收敛'])
S(c,'级数判别练习',[R('题目',r'\sum_{n=1}^{\infty}\frac{n}{3^n}'),T('任务','判断敛散性，写出使用的判别法与关键极限')],[P('暂停判断：n除以三的n次方相加，是否收敛？请写下一项与当前项的比值，并计算极限。不要只说指数增长快于一次函数，就省去可检查的关键算式。尤其分子从n变为n加一，分母从三的n次方变为三的n加一次方，两个变化都必须写对。',[1,2],['先写完整的下一项','极限结果与一比较'])],['比值与根值判别'],kind='question')
S(c,'级数判别练习答案',[R('比值',r'\frac{a_{n+1}}{a_n}=\frac{n+1}{3n}'),R('比值极限小于一，收敛',r'\rho=\frac13<1')],[P('比值是n加一除以三n，极限三分之一，小于一，所以级数收敛。本题各项为正，也可说绝对收敛。注意比值法问的是下一项除以当前项的极限，不是通项本身的极限；通项趋零只是必要条件，而比值极限严格小于一才在这里提供了足够的收敛判据。',[1,2],['比值极限三分之一，小于一','区分通项极限与比值极限'])],['比值与根值判别'],kind='answer')

c=C('幂级数与傅里叶级数')
S(c,'收敛半径以后，端点分别代回',[R('以一为中心的幂级数：通项',r'a_n(x)=\frac{(x-1)^n}{n2^n},\quad n=1,2,\ldots'),R('比值判别得到内部',r'\rho=\frac{|x-1|}{2}<1\quad\Longrightarrow\quad -1<x<3,\quad R=2'),R('端点对应通项：左收敛、右发散',r'x=-1:\frac{(-1)^n}{n};\quad x=3:\frac1n;\quad I=[-1,3)')],[P('先在数轴上标出级数的中心一。幂级数把x当成参数，用绝对值比值法得到绝对值x减一除以二，小于一时收敛，所以内部区间负一到三，收敛半径二。半径只描述离中心允许多远，不告诉我们两个端点是否包含，因此不能在这里直接交最终闭开区间。',[1,2],['中心是一，收敛半径二','半径计算以后仍有端点任务'],phase='radius',anchor='先在数轴上标出级数的中心一'),P('现在分别把两个端点代回原级数。左端变成交错调和，收敛；右端变成普通调和，发散，所以收敛区间左闭右开。两个端点可能一个收敛、一个发散，也可能同样收敛或发散，必须分别检查。不要把绝对值不等式里的严格小于，直接当成所有端点都发散的证明。',[3],['端点代回原式，不代入失效的比值结论','本题左闭右开'],phase='endpoints',anchor='现在分别把两个端点代回原级数')],['幂级数收敛半径与区间'],visual=G('interval'))
S(c,'逐项求导与积分：半径不变，端点重查',[R('基本等比展开',r'\frac1{1-x}=\sum_{n=0}^{\infty}x^n,\qquad |x|<1'),R('逐项求导',r'\frac1{(1-x)^2}=\sum_{n=1}^{\infty}n x^{n-1}'),R('从零积分到x',r'-\ln(1-x)=\sum_{n=1}^{\infty}\frac{x^n}{n},\qquad |x|<1'),T('区间提醒','在收敛半径内部可逐项处理；求导或积分后端点性质可能变化')],[P('在收敛半径内部，幂级数可以逐项求导与积分，收敛半径保持不变。最常用出发点是等比展开。对两边求导，常数项一的导数为零，所以新级数从n等于一开始，系数多出n，指数减一。下标与指数一起检查，避免凭印象把常数项留在一个错误的负次幂里。',[1,2],['求导后系数乘n，指数减一','常数项消失，注意起始下标']),P('若从零到x积分，左边得到负的自然对数一减x，右边把每个幂积分，就得到x的n次方除以n的和。用定积分从零出发，可以清楚固定积分常数。半径仍为一，但原来端点处的敛散性可能变化，因此逐项运算的常用保证是开区间内部，端点仍需单独代回检查。',[3,4],['半径不变不代表端点行为不变','定积分起点用来确定常数'])],['幂级数逐项运算'])
S(c,'常用麦克劳林展开与适用范围',[R('指数函数',r'e^x=\sum_{n=0}^{\infty}\frac{x^n}{n!},\qquad x\in\mathbb R'),R('正弦与余弦',r'\sin x=\sum_{n=0}^{\infty}\frac{(-1)^n x^{2n+1}}{(2n+1)!},\quad\cos x=\sum_{n=0}^{\infty}\frac{(-1)^n x^{2n}}{(2n)!}'),R('对数常用开区间形式',r'\ln(1+x)=\sum_{n=1}^{\infty}\frac{(-1)^{n-1}x^n}{n},\qquad |x|<1'),R('一般系数',r'a_n=\frac{f^{(n)}(0)}{n!}')],[P('常用展开优先记四类：指数、正弦、余弦，以及一加x的自然对数。指数每一阶都有；正弦只有奇次幂，余弦只有偶次幂，两者符号交替。分母的阶乘要跟实际幂次一致，不是所有项都写n阶乘。前三个展开对所有实数成立，对数要额外关注收敛范围。',[1,2,3],['正弦奇次，余弦偶次，符号交替','分母阶乘跟实际幂次配套']),P('麦克劳林系数来自零点处的各阶导数除以相应阶乘。实际做基础题时，优先从已经记住的展开通过代换、求导或积分得到所需形式，不必每题都从头求很多阶导。对一般函数，形式上写出的泰勒级数还要有等于原函数的依据，不能把存在所有阶导数当成无条件等于展开的保证。',[4],['常用展开可通过代换快速应用','一般函数不能无条件等于其泰勒级数'])],['泰勒与麦克劳林展开'])
S(c,'展开应用：代换、取系数与求极限',[R('把x换成x平方',r'e^{x^2}=1+x^2+\frac{x^4}{2!}+\frac{x^6}{3!}+\cdots'),R('指定幂次的系数',r'[x^6]e^{x^2}=\frac1{3!}=\frac16'),R('保留足够阶数',r'\lim_{x\to0}\frac{e^x-1-x}{x^2}=\frac12')],[P('先看多项式逐步靠近指数曲线。要求e的x平方展开，只需在指数函数的已知展开中，把每个x都替换成x平方，因此指数变成零、二、四、六。x六次方来自原来的第三阶项，所以系数是三阶乘分之一，也就是六分之一，不是六阶乘分之一。',[1,2],['先找哪一项产生目标幂次','代换改变幂次，不随意改阶乘'],phase='taylor',anchor='先看多项式逐步靠近指数曲线'),P('现在把展开截到求极限需要的阶数。e的x次方减一再减x，前两项被消去，剩下x平方的一半和更高阶项，除以x平方后极限为二分之一。若只保留一阶，就把关键信息丢掉了。使用展开求极限，先看分母阶数与分子会消掉几项，再决定需要写到哪一阶。',[3],['先看抵消，再决定保留阶数','高阶余项必须在相应极限中可忽略'],phase='limit',anchor='现在把展开截到求极限需要的阶数')],['幂级数应用'],visual=G('taylor'))
S(c,'傅里叶级数：先统一周期与系数约定',[R('周期二π的写法',r'f(x)\sim\frac{a_0}{2}+\sum_{n=1}^{\infty}(a_n\cos nx+b_n\sin nx)'),R('余弦系数与常数项',r'a_n=\frac1\pi\int_{-\pi}^{\pi}f(x)\cos nx\,dx,\quad n=0,1,\ldots'),R('正弦系数',r'b_n=\frac1\pi\int_{-\pi}^{\pi}f(x)\sin nx\,dx,\quad n\geq1'),T('奇偶性先化简','偶函数的bn为零；奇函数的a0与an为零')],[P('傅里叶级数使用正弦和余弦，不是x的连续幂。先记清本页采用周期二π、常数项a零除以二的约定；计算a零的公式前面仍是一除以π，不能又悄悄除一次二。先抄周期和展开形式，再计算系数，避免把不同教材的系数规范混用在同一道题里。',[1,2,3],['先确定周期与a零除以二的约定','正弦与余弦系数分开计算']),P('奇偶性可以省去一半计算。偶函数只留下余弦项和常数项，奇函数只留下正弦项，因为相应乘积在对称区间上为奇函数而积分为零。周期为二L时，频率应改成nπ除以L，系数前因子改成一除以L；不能沿用周期二π的频率，却只替换积分上下限。',[4],['先判奇偶，能少算一类系数','周期变化时，频率与系数因子一起改变'])],['傅里叶级数与系数'])
S(c,'傅里叶例题与间断点的和',[R('区间内函数与奇偶性',r'f(x)=x,\quad-\pi<x<\pi,\qquad a_0=a_n=0'),R('正弦系数',r'b_n=\frac2\pi\int_0^\pi x\sin nx\,dx=\frac{2(-1)^{n+1}}n'),R('展开前几项；拼接端点的和为零',r'x\sim2\sin x-\sin 2x+\frac23\sin 3x-\cdots;\quad S(\pm\pi)=0')],[P('先画出按周期延拓后的锯齿形函数。区间内f等于x，是奇函数，因此只算正弦系数。把对称积分变成零到π的二倍，再用分部积分，得到二乘负一的n加一次方除以n。前几项分别是二正弦x、减正弦二x、加三分之二正弦三x，系数和频率不要混在一起。',[1,2],['奇函数只保留正弦项','系数交替，频率随n增加'],phase='fourier',anchor='先画出按周期延拓后的锯齿形函数'),P('现在观察拼接处两侧的函数值。在常用分段光滑条件下，连续点处级数和等于函数值；跳跃点处等于左右极限的平均。本例周期拼接处，一侧趋于π，另一侧趋于负π，因此级数和为零，不是π。图上的截断波形会有局部振荡，不能把有限项曲线当成已经处处等于原函数。',[3],['跳跃处取左右极限的平均','有限项图示只是部分和近似'],phase='jump',anchor='现在观察拼接处两侧的函数值')],['傅里叶展开与收敛值'],visual=G('fourier'))
S(c,'幂级数收敛区间练习',[R('题目',r'\sum_{n=0}^{\infty}\frac{(x-2)^n}{3^n}'),T('任务','求收敛半径和收敛区间，两个端点分别判断')],[P('暂停练习：中心为二、分母为三的n次方的幂级数，从n等于零开始。请写出公比、收敛半径和最终区间，再把两个端点分别代回去。注意这是几何级数，端点处即使正负交错，如果通项没有趋零，也不能使用莱布尼茨条件宣称收敛。',[1,2],['先看公比的绝对值','端点先检查通项是否趋零'])],['幂级数收敛半径与区间'],kind='question')
S(c,'幂级数练习答案',[R('内部条件',r'\left|\frac{x-2}{3}\right|<1\quad\Longrightarrow\quad -1<x<5'),R('端点检查',r'x=-1:\ a_n=(-1)^n;\qquad x=5:\ a_n=1'),R('结果',r'R=3,\qquad I=(-1,5)')],[P('收敛半径三，区间负一到五，两端都不含。左端每项正负一交替，通项不趋零；右端每项都是一，也不趋零，所以都发散。这个例子与前面带一个n作分母的题不同：同样的半径计算方式，端点却可能改变。最后把半径和区间各写一遍，确保没有只给出其中一个。',[1,2,3],['半径三，两个端点都发散','交错符号不能代替趋零条件'])],['幂级数收敛半径与区间'],kind='answer')
S(c,'考前回顾：先条件，再模板，最后核对',[T('空间与微分','向量先分点积叉积；求导先列依赖；极值先列候选再判别'),T('积分','先看积分对象、区域与方向，再选坐标或公式'),T('级数','先通项筛选，再选判别法；半径之后端点分别检查')],[P('最后按做题顺序回顾。空间题先分清点、方向和法向；多元求导先写自变量依赖，再逐条路径计算；极值题在候选点之外还要看边界，判别量为零时换方法。重积分先画区域、选坐标、写上下限，再由里向外计算。每道题先把条件和第一步正确写出，比凭感觉直接猜最后一个数更可靠。',[1,2],['把题型与条件写在公式之前','上下限、取向和变量是重点检查项']),P('曲线曲面积分先分第一类还是第二类，再检查是否闭合与方向是否匹配，选格林、高斯或斯托克斯。级数先看通项，幂级数算半径后别漏端点。看完以后合上答案，把十道练习重做一遍，再按本校往年卷补足范围和熟练度。一个小时能帮你建立计算路线，真正落到卷面，还要练到自己能独立写出步骤。',[3],['十道练习至少独立重做一遍','用本校考纲和往年题确认范围与熟练度'])],['综合回顾'])
